mapper.select:
SELECT r.RegistrationID as id, r.AthleteID as athleteId, a.Name as athleteName, a.Gender as gender, a.grade as grade, a.Contact as contact, r.EventID as eventId, e.EventName as eventName, r.ItemID as itemId, p.ItemName as itemName, r.RegistrationTime as registrationTime, r.RegistrationStatus as registrationStatus FROM Registration r LEFT JOIN Athlete a ON r.AthleteID = a.AthleteID LEFT JOIN Event e ON r.EventID = e.EventID LEFT JOIN Eventitem p ON r.ItemID = p.ItemID
AND r.EventID = #{eventId}
ORDER BY r.RegistrationTime DESC
